import java.util.*; import java.util.regex.*; class Solution { static Set<String> ids(String fxml){ Matcher matcher=Pattern.compile("fx:id=\"([A-Za-z][A-Za-z0-9_]*)\"").matcher(fxml); Set<String> ids=new LinkedHashSet<>(); while(matcher.find()) if(!ids.add(matcher.group(1))) throw new IllegalArgumentException("duplicate fx:id"); return Set.copyOf(ids);} static String cssClass(String value){ String normalized=value.trim().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]+","-"); if(normalized.isBlank()) throw new IllegalArgumentException("css"); return normalized;} }
